/*
 * uilib foundation: tokens, density and motion.
 * Import once after Tailwind: @import "tailwindcss"; @import "./uilib.css";
 * Every component reads from these variables, so restyling happens here, not per component.
 */

@custom-variant dark (&:where(.dark, .dark *));

/* Raw palette. Light steps are true greys so light mode reads as plain white; the dark
   steps keep a faint warmth, which is invisible as tint but softens large dark areas. */
:root {
  --uil-neutral-0: oklch(100% 0 0);
  --uil-neutral-25: oklch(98.8% 0 0);
  --uil-neutral-50: oklch(97.3% 0 0);
  --uil-neutral-100: oklch(95% 0 0);
  --uil-neutral-200: oklch(91% 0 0);
  --uil-neutral-300: oklch(85% 0 0);
  --uil-neutral-400: oklch(70% 0 0);
  --uil-neutral-500: oklch(56% 0 0);
  --uil-neutral-600: oklch(45% 0 0);
  --uil-neutral-700: oklch(35% 0.012 85);
  --uil-neutral-800: oklch(26% 0.01 85);
  --uil-neutral-850: oklch(22% 0.009 85);
  --uil-neutral-900: oklch(18.5% 0.008 85);
  --uil-neutral-950: oklch(14.5% 0.007 85);
  --uil-red-500: oklch(58% 0.19 30);
  --uil-red-400: oklch(66% 0.17 30);
}

/* Semantic tokens. Components only ever use these. */
:root {
  --uil-bg: var(--uil-neutral-0);
  --uil-surface: var(--uil-neutral-0);
  --uil-surface-muted: var(--uil-neutral-50);
  --uil-surface-hover: var(--uil-neutral-100);
  --uil-surface-active: var(--uil-neutral-200);
  --uil-fg: var(--uil-neutral-950);
  --uil-fg-muted: var(--uil-neutral-600);
  --uil-fg-subtle: var(--uil-neutral-500);
  --uil-border: var(--uil-neutral-200);
  --uil-border-strong: var(--uil-neutral-300);
  --uil-primary: var(--uil-neutral-900);
  --uil-primary-hover: var(--uil-neutral-800);
  --uil-primary-fg: var(--uil-neutral-25);
  --uil-danger: var(--uil-red-500);
  --uil-danger-fg: var(--uil-neutral-0);
  --uil-ring: var(--uil-neutral-950);
  --uil-backdrop: oklch(14.5% 0 0 / 0.32);
  /* The only shadow in the system: floating layers need depth to separate from content. */
  --uil-shadow-float: 0 8px 24px -10px oklch(14.5% 0.007 85 / 0.18),
    0 2px 6px -2px oklch(14.5% 0.007 85 / 0.06);
}

.dark {
  --uil-bg: var(--uil-neutral-950);
  --uil-surface: var(--uil-neutral-900);
  --uil-surface-muted: var(--uil-neutral-900);
  --uil-surface-hover: var(--uil-neutral-850);
  --uil-surface-active: var(--uil-neutral-800);
  --uil-fg: var(--uil-neutral-50);
  --uil-fg-muted: var(--uil-neutral-400);
  --uil-fg-subtle: var(--uil-neutral-500);
  --uil-border: var(--uil-neutral-800);
  --uil-border-strong: var(--uil-neutral-700);
  --uil-primary: var(--uil-neutral-50);
  --uil-primary-hover: var(--uil-neutral-200);
  --uil-primary-fg: var(--uil-neutral-950);
  --uil-danger: var(--uil-red-400);
  --uil-ring: var(--uil-neutral-50);
  --uil-backdrop: oklch(0% 0 0 / 0.6);
  --uil-shadow-float: 0 8px 24px -8px oklch(0% 0 0 / 0.6);
  color-scheme: dark;
}

/* Density. Set data-density on any container; descendants resize without new classes. */
:root,
[data-density="default"] {
  --uil-control-h: 2rem;
  --uil-control-px: 0.75rem;
  --uil-item-h: 2rem;
  --uil-text: 0.875rem;
}
[data-density="compact"] {
  --uil-control-h: 1.75rem;
  --uil-control-px: 0.625rem;
  --uil-item-h: 1.75rem;
  --uil-text: 0.8125rem;
}
[data-density="comfortable"] {
  --uil-control-h: 2.5rem;
  --uil-control-px: 1rem;
  --uil-item-h: 2.25rem;
  --uil-text: 0.9375rem;
}
/* Touch needs real targets no matter the density. */
@media (pointer: coarse) {
  :root,
  [data-density] {
    --uil-control-h: 2.75rem;
    --uil-item-h: 2.75rem;
  }
}

/* Motion tokens. Nothing in the core goes above --uil-duration-slow. */
:root {
  --uil-duration-fast: 120ms;
  --uil-duration-base: 160ms;
  --uil-duration-slow: 220ms;
  /* Exits run at ~0.7x so dismissing never feels slower than opening. */
  --uil-duration-exit: 110ms;
  --uil-ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
  --uil-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --uil-pop-scale: 0.96;
  --uil-pop-shift: 4px;
}

@theme inline {
  --color-bg: var(--uil-bg);
  --color-surface: var(--uil-surface);
  --color-surface-muted: var(--uil-surface-muted);
  --color-surface-hover: var(--uil-surface-hover);
  --color-surface-active: var(--uil-surface-active);
  --color-fg: var(--uil-fg);
  --color-fg-muted: var(--uil-fg-muted);
  --color-fg-subtle: var(--uil-fg-subtle);
  --color-border: var(--uil-border);
  --color-border-strong: var(--uil-border-strong);
  --color-primary: var(--uil-primary);
  --color-primary-hover: var(--uil-primary-hover);
  --color-primary-fg: var(--uil-primary-fg);
  --color-danger: var(--uil-danger);
  --color-danger-fg: var(--uil-danger-fg);
  --color-ring: var(--uil-ring);
  --color-backdrop: var(--uil-backdrop);
  --shadow-float: var(--uil-shadow-float);
  --radius-control: 0.5rem;
  --radius-float: 0.75rem;
}

/*
 * Motion utilities. Components never hand-roll transitions; they pick one of these.
 * All are CSS transitions (interruptible mid-flight), honour Base UI's data-instant,
 * skip animation when the user is driving with the keyboard, and keep only the
 * fade under prefers-reduced-motion or an app-level <html data-motion="reduced">.
 */

/* Popovers, menus, tooltips: scale out of the trigger. */
@utility motion-pop {
  transform-origin: var(--transform-origin, center);
  transition-property: opacity, scale;
  transition-duration: var(--uil-duration-base);
  transition-timing-function: var(--uil-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    scale: var(--uil-pop-scale);
  }
  &[data-ending-style] {
    transition-duration: var(--uil-duration-exit);
  }
  &[data-instant],
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    scale: 1;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      scale: 1;
    }
  }
}

/* Dialogs: a small lift instead of a zoom; large surfaces that scale look sluggish. */
@utility motion-dialog {
  transition-property: opacity, scale, translate;
  transition-duration: var(--uil-duration-slow);
  transition-timing-function: var(--uil-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    scale: 0.98;
    translate: 0 var(--uil-pop-shift);
  }
  &[data-ending-style] {
    transition-duration: var(--uil-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    scale: 1;
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      scale: 1;
      translate: 0 0;
    }
  }
}

/*
 * Sheets: slide in from an edge set by --uil-sheet-hidden (e.g. translateX(100%)) and
 * follow the finger while swiping (Base UI Drawer's swipe variables).
 */
@utility motion-sheet {
  transform: translate(var(--drawer-swipe-movement-x, 0px), var(--drawer-swipe-movement-y, 0px));
  transition-property: transform, opacity;
  transition-duration: var(--uil-duration-slow);
  transition-timing-function: var(--uil-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    transform: var(--uil-sheet-hidden);
  }
  &[data-ending-style] {
    transition-duration: var(--uil-duration-exit);
  }
  &[data-swiping] {
    transition-duration: 0ms;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    transform: none;
    opacity: 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      transform: none;
      opacity: 0;
    }
  }
}

/* Backdrops and anything that only needs opacity. */
@utility motion-fade {
  transition-property: opacity;
  transition-duration: var(--uil-duration-base);
  transition-timing-function: var(--uil-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
  }
  &[data-ending-style] {
    transition-duration: var(--uil-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
}

/* Hover and press feedback. Paint-only properties so it can never shift layout. */
@utility motion-control {
  transition-property: color, background-color, border-color, box-shadow, scale;
  transition-duration: var(--uil-duration-fast);
  transition-timing-function: var(--uil-ease-out);
}

/*
 * Label swaps inside a control (confirm steps, status text). Stack every state in one
 * grid cell so the control keeps the width of its longest label, then mark the
 * inactive ones data-swap="out". A quick crossfade with a hint of lift.
 */
@utility motion-swap {
  transition-property: opacity, translate;
  transition-duration: var(--uil-duration-fast);
  transition-timing-function: var(--uil-ease-out);
  &[data-swap="out"] {
    opacity: 0;
    translate: 0 0.3em;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-swap="out"] {
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-swap="out"] {
      translate: 0 0;
    }
  }
}

/* Inline messages under a control (field errors, hints): a short drop from the control. */
@utility motion-message {
  transition-property: opacity, translate;
  transition-duration: var(--uil-duration-fast);
  transition-timing-function: var(--uil-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    translate: 0 -0.25em;
  }
  &[data-ending-style] {
    transition-duration: var(--uil-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      translate: 0 0;
    }
  }
}

/* Shared focus ring, keyboard focus only. */
@utility focus-ring {
  outline: 2px solid transparent;
  outline-offset: 2px;
  &:focus-visible {
    outline-color: var(--uil-ring);
  }
}

/* Numbers in data UIs should not jitter while they update. */
@utility nums {
  font-variant-numeric: tabular-nums;
}
